void ScriptSession::bindIllusionNatives() {
    bind("IsUnitIllusion","boolean",{"unit"},[this](auto& vm,auto a){return vm.boolean(alive(a[0].bits,NativeKind::Unit) && unit(a[0]).illusion);});
    bind("UnitApplyTimedLife","nothing",{"unit","integer","real"},[this](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();auto duration=number(jass::Real::fromBits(a[2].bits));if(!std::isfinite(duration) || duration<0 || duration>86400)throw std::runtime_error("Timed life duration outside supported range");auto& u=unit(a[0]);if(u.earlierTimedLives.size()>=4095)throw std::runtime_error("Timed life count exceeds budget");auto buff=a[1].bits;bool known=false;for(auto code:{"BUan","BFig","BEfn","Bhwd","Bplg","Brai","BHwe"})if(buff==ObjectData::code(code)){known=true;break;}if(!known)buff=ObjectData::code("BTLF");u.sourceSummoned=true;u.removedTypes&=~(std::uint32_t(1)<<10);u.addTimedLife(TimedLife{buff,duration,duration,false});u.abilities[buff]=1;return vm.nothing();});
    bind("UnitPauseTimedLife","nothing",{"unit","boolean"},[this](auto& vm,auto a){if(!alive(a[0].bits,NativeKind::Unit))return vm.nothing();auto& u=unit(a[0]);if(u.timedLife)u.timedLife->paused=a[1].bits!=0;for(auto& life:u.earlierTimedLives)life.paused=a[1].bits!=0;return vm.nothing();});
    bind("GetSummoningUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().summoningUnit);});
    bind("GetSummonedUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().summonedUnit);});
}
